from pathlib import Path
import json

def scaffold(path: Path, adapter: str, name: str):
    path.mkdir(parents=True, exist_ok=True)
    if adapter == "nextjs":
        files = {
            "package.json": json.dumps({"name": name, "private": True, "scripts": {"dev": "next dev", "build": "next build", "start": "next start"}, "dependencies": {"next": "^15.0.0", "react": "^19.0.0", "react-dom": "^19.0.0"}, "devDependencies": {"typescript": "^5.0.0", "@types/react": "^19.0.0", "@types/node": "^22.0.0"}}, indent=2)+"\n",
            "next.config.mjs": "export default { output: 'standalone' };\n",
            "app/layout.tsx": 'import type { ReactNode } from "react";\nexport default function Layout({children}: {children:ReactNode}) { return <html lang="en"><body>{children}</body></html>; }\n',
            "app/page.tsx": "export default function Page() { return <h1>Generated by forger</h1>; }\n",
            "tsconfig.json": json.dumps({"compilerOptions":{"target":"ES2017","lib":["dom","dom.iterable","esnext"],"allowJs":True,"skipLibCheck":True,"strict":True,"noEmit":True,"esModuleInterop":True,"module":"esnext","moduleResolution":"bundler","resolveJsonModule":True,"isolatedModules":True,"jsx":"preserve","incremental":True,"plugins":[{"name":"next"}]},"include":["next-env.d.ts","**/*.ts","**/*.tsx",".next/types/**/*.ts"],"exclude":["node_modules"]},indent=2)+"\n",
            "public/.gitkeep":""
        }
    elif adapter == "spring-boot-maven":
        files={
            "pom.xml": '''<project xmlns="http://maven.apache.org/POM/4.0.0" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xsi:schemaLocation="http://maven.apache.org/POM/4.0.0 https://maven.apache.org/xsd/maven-4.0.0.xsd"><modelVersion>4.0.0</modelVersion><parent><groupId>org.springframework.boot</groupId><artifactId>spring-boot-starter-parent</artifactId><version>3.5.0</version><relativePath/></parent><groupId>dev.forger</groupId><artifactId>app</artifactId><version>0.0.1-SNAPSHOT</version><properties><java.version>21</java.version></properties><dependencies><dependency><groupId>org.springframework.boot</groupId><artifactId>spring-boot-starter-web</artifactId></dependency><dependency><groupId>org.springframework.boot</groupId><artifactId>spring-boot-starter-actuator</artifactId></dependency><dependency><groupId>org.springframework.boot</groupId><artifactId>spring-boot-starter-data-mongodb</artifactId></dependency></dependencies><build><plugins><plugin><groupId>org.springframework.boot</groupId><artifactId>spring-boot-maven-plugin</artifactId></plugin></plugins></build></project>\n''',
            "src/main/java/dev/forger/app/Application.java": "package dev.forger.app;\nimport org.springframework.boot.SpringApplication;\nimport org.springframework.boot.autoconfigure.SpringBootApplication;\n@SpringBootApplication public class Application { public static void main(String[] a) { SpringApplication.run(Application.class,a); } }\n",
            "src/main/java/dev/forger/app/HealthController.java": 'package dev.forger.app;\nimport org.springframework.web.bind.annotation.*;\n@RestController public class HealthController { @GetMapping("/api/hello") public String hello(){return "Hello from forger";} }\n',
            "src/main/resources/application.properties":"management.endpoints.web.exposure.include=health,info\n"
        }
    else: raise ValueError("Cannot scaffold generic Dockerfile projects")
    created=[]
    for filename, content in files.items():
        dest=path/filename
        if dest.exists(): continue
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_text(content, encoding="utf8")
        created.append(dest)
    return created
